INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pine-dark', 'south', 'the-murk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-murk', 'north', 'the-pine-dark', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-alders', 'south', 'the-black-alder-stand', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-black-alder-stand', 'north', 'the-black-alders', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sapling-crowd', 'east', 'the-buckled-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-buckled-ground', 'west', 'the-sapling-crowd', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wild-cherry', 'south', 'the-deep-roots', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-roots', 'north', 'the-wild-cherry', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-roots', 'south', 'the-dark-behind', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-boundary-cross', 'south', 'the-pay-stone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-pay-stone', 'north', 'the-boundary-cross', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-soft-floor', 'south', 'the-sunk-moss', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sunk-moss', 'door', 'The Sunk Moss', 'The soft floor goes down here into a long hollow, the moss deeper still, so you wade in it to the shin, and it closes over each step behind you. Along one side of the hollow the ground rises into a bank, and roots come out of the bank in a wall.', 0, 0, 'wood', 0, -53, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-moss', 'north', 'the-soft-floor', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-moss', 'east', 'the-under-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-under-bank', 'door', 'The Under-Bank', 'You go along under a bank where the ground has fallen away from the roots of a row of great trees, the roots hanging over you, tangled and dripping, furred with moss. Water drips from them onto your shoulders. Between them there are gaps, and behind the gaps it is dark.', 0, 0, 'wood', 0, -52, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-bank', 'west', 'the-sunk-moss', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-under-bank', 'east', 'the-dark-behind', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-dark-behind', 'door', 'The Dark Behind', 'Behind the wall of roots there is a space, a hollow under the trees where the ground has gone, roofed by roots and walled by roots, black and cool and smelling of wet earth. Something has slept here. Through the roots on the north side there is a grey of open wood.', 0, 0, 'wood', 0, -51, 11, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dark-behind', 'west', 'the-under-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dark-behind', 'north', 'the-deep-roots', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-bounds-house', 'east', 'the-cut-line', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-cut-line', 'door', 'The Cut Line', 'The coppice round the counting house stops here at a line as straight as a ruled edge, the stools on one side cut and cut again for a hundred years and the old trees on the other never cut at all. A ride runs along the line, kept open by feet. It goes east toward the old gatehouse ground.', 0, 0, 'wood', 0, -46, -8, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut-line', 'west', 'the-bounds-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cut-line', 'east', 'the-tally-posts', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-tally-posts', 'door', 'The Tally Posts', 'Oak posts stand along the ride at every twentieth pace, grey and split, each one notched down its side in fives the way the rods in the counting house are tied. Somebody walked this line and counted. The posts go on east to where the ground opens by the road.', 0, 0, 'wood', 0, -45, -8, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tally-posts', 'west', 'the-cut-line', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-tally-posts', 'east', 'the-mounting-block', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-mounting-block', 'west', 'the-tally-posts', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rampart-walk', 'east', 'the-postern-gap', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-postern-gap', 'door', 'The Postern Gap', 'The bank of the old gatehouse ground is broken through here at its back, where a small gate once let people out without opening the great one. The gateposts are stumps. Beyond the gap a road goes off away from the gatehouse, down toward the wood.', 0, 0, 'wood', 0, -39, -9, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-postern-gap', 'west', 'the-rampart-walk', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-postern-gap', 'south', 'the-back-road', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-back-road', 'door', 'The Back Road', 'A road runs off behind the gatehouse, metalled once with flint and still hard under the turf, wide enough for a cart. Nobody came to the front gate by this road. It went to the wood, for the wood''s timber and charcoal, and it still goes there.', 0, 0, 'wood', 0, -39, -8, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-road', 'north', 'the-postern-gap', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-road', 'east', 'the-sunk-paving', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-sunk-paving', 'door', 'The Sunk Paving', 'The road''s paving has sunk in the middle under a long weight of carts, and the two ruts are worn into the stone a hand deep, and water lies in them, and moss along their lips. Grass has the crown of the road. The ruts go on east.', 0, 0, 'wood', 0, -38, -8, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-paving', 'west', 'the-back-road', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-sunk-paving', 'east', 'the-fallen-milestone', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-fallen-milestone', 'door', 'The Fallen Milestone', 'A milestone lies on its face in the verge, its foot still in the hole it stood in. Somebody has dug round it and turned it partway, to read it, and let it fall back. Whatever it says is underneath.', 0, 0, 'wood', 0, -37, -8, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-milestone', 'west', 'the-sunk-paving', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-fallen-milestone', 'east', 'the-road-bend', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-road-bend', 'door', 'The Road Bend', 'The road turns south here and starts down off the high ground toward the trees, the verges closing in, the first oaks leaning over it. Looking back, the bank of the gatehouse ground is a long green line against the sky.', 0, 0, 'wood', 0, -36, -8, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-road-bend', 'west', 'the-fallen-milestone', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-road-bend', 'south', 'the-holloway-head', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-holloway-head', 'door', 'The Holloway Head', 'The road begins to sink between banks, worn down below the ground by the wheels and the rain, the banks rising on both sides to your knee, then your waist. Roots come out of them. The light from above narrows to a strip.', 0, 0, 'wood', 0, -36, -7, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holloway-head', 'north', 'the-road-bend', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-holloway-head', 'south', 'the-deep-holloway', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-deep-holloway', 'door', 'The Deep Holloway', 'The road runs at the bottom of a cut deeper than a man is tall, the banks sheer and overhung, the trees along their tops meeting over the road so it goes through a green tunnel. Your steps sound on the hard floor. Anything on the banks above could watch you all the way.', 0, 0, 'wood', 0, -36, -6, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-holloway', 'north', 'the-holloway-head', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deep-holloway', 'south', 'the-root-bridge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-root-bridge', 'door', 'The Root Bridge', 'The roots of two oaks on opposite banks have met over the holloway and grown into each other, so a bridge of living root crosses the road at the height of your head. Something uses it. The bark on top of it is worn smooth and the moss is gone.', 0, 0, 'wood', 0, -36, -5, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-bridge', 'north', 'the-deep-holloway', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-root-bridge', 'south', 'the-rotted-cart', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-rotted-cart', 'door', 'The Rotted Cart', 'A cart stands in the holloway where it stopped, its wheels sunk to the hubs in the road''s mud, its bed rotted through, the shafts lying on the ground in front of it with no harness. A load of charcoal is still in it, black under the leaf litter. It was going up the road, to the gatehouse.', 0, 0, 'wood', 0, -36, -4, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rotted-cart', 'north', 'the-root-bridge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-rotted-cart', 'south', 'the-washout', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-washout', 'door', 'The Washout', 'Water has used the holloway as a stream for years and torn the road out of its bottom, leaving the old paving in broken slabs tumbled among stones. You climb down over them. The banks have slipped in places and the road is half buried.', 0, 0, 'wood', 0, -36, -3, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-washout', 'north', 'the-rotted-cart', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-washout', 'south', 'the-wet-lane', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-wet-lane', 'door', 'The Wet Lane', 'The holloway shallows out and the road goes on as a wet lane between low banks, puddled from side to side, reeds coming up in the ruts. From ahead comes a great racket of frogs. On the bank to the west the ground drops away into a dark under roots.', 0, 0, 'wood', 0, -36, -2, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-lane', 'north', 'the-washout', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-wet-lane', 'south', 'the-lanes-end', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y, map_z) VALUES
  ('the-lanes-end', 'door', 'The Lane''s End', 'The road gives out here among reeds and standing water, the last of the paving going down under the wet and not coming up. It was a road to the wood and it reached it. The frogs are very loud.', 0, 0, 'wood', 0, -36, -1, 0);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lanes-end', 'north', 'the-wet-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-lanes-end', 'south', 'the-frog-chorus', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-frog-chorus', 'north', 'the-lanes-end', NULL);
